using Amifolio.Core;
using System.Text.Json;

internal static class ReferenceCases
{
    internal static (string,Func<Fixture,Task>)[] All =>
    [
        ("reference mode refuses manual import and project mutation",async f=>{var (s,p,file)=await Setup(f);await Reject(()=>s.CreateProjectAsync("manual",p.RootPath));await Reject(()=>s.ImportFileAsync(file,p.Id));await Reject(()=>s.ImportRepositoryAsync(p.RootPath!));Check((await s.ProjectsAsync()).Count==1);}),
        ("reference metadata indexes original path without copy or analysis",async f=>{var (s,p,file)=await Setup(f);var time=File.GetLastWriteTimeUtc(file);var attrs=File.GetAttributes(file);var r=await s.ReferenceFileAsync(file,p.Id);Check(r.Artifact.IsReference&&r.Artifact.ObjectPath==file&&r.Artifact.Preview==""&&r.Artifact.ExtractionStatus=="未解析");Check(!Directory.EnumerateFiles(Path.Combine(f.DataRoot,"objects")).Any());Check(File.GetLastWriteTimeUtc(file)==time&&File.GetAttributes(file)==attrs);Check((await new TaskStore(f.DataRoot).ListAsync()).Count==0);}),
        ("reference explicit parsing retains read-only source and line locator",async f=>{var (s,p,file)=await Setup(f);var r=await s.ReferenceFileAsync(file,p.Id);await s.ParseReferenceAsync(r.Artifact.Id);var got=await s.GetAsync(r.Artifact.Id);Check(got!.Preview.Contains("[行 1]")&&got.Preview.Contains("needle"));Check(await File.ReadAllTextAsync(file)=="needle 原文");Check(!Directory.EnumerateFiles(Path.Combine(f.DataRoot,"objects")).Any());}),
        ("reference changed source invalidates cached preview",async f=>{var (s,p,file)=await Setup(f);var r=await s.ReferenceFileAsync(file,p.Id);await s.ParseReferenceAsync(r.Artifact.Id);await File.WriteAllTextAsync(file,"new different source");var got=await s.GetAsync(r.Artifact.Id);Check(got!.Preview==""&&got.ExtractionStatus.Contains("变化"));Check((await s.ListAsync()).Single().Preview=="");}),
        ("reference explicit detail detects equal-size equal-time replacement",async f=>{var(s,p,file)=await Setup(f);var r=await s.ReferenceFileAsync(file,p.Id);await s.ParseReferenceAsync(r.Artifact.Id);var time=File.GetLastWriteTimeUtc(file);await File.WriteAllTextAsync(file,"NEEDLE 原文");File.SetLastWriteTimeUtc(file,time);var live=await s.GetAsync(r.Artifact.Id);Check(live!.Preview==""&&live.ExtractionStatus.Contains("变化"));}),
        ("reference parser holds source read lease through extraction",async f=>{var(s,p,file)=await Setup(f);var r=await s.ReferenceFileAsync(file,p.Id);var blocked=false;StorageFaults.Handler.Value=stage=>{if(stage!="extract")return;try{using var writer=new FileStream(file,FileMode.Open,FileAccess.Write,FileShare.ReadWrite);}catch(IOException){blocked=true;}};try{await s.ParseReferenceAsync(r.Artifact.Id);}finally{StorageFaults.Handler.Value=null;}Check(blocked&&await File.ReadAllTextAsync(file)=="needle 原文");}),
        ("reference missing source remains visible without stale text",async f=>{var (s,p,file)=await Setup(f);var r=await s.ReferenceFileAsync(file,p.Id);await s.ParseReferenceAsync(r.Artifact.Id);File.Delete(file);var got=await s.GetAsync(r.Artifact.Id);Check(got!.Preview==""&&got.ExtractionStatus.Contains("缺失"));await Reject(()=>s.GetOriginalPathAsync(r.Artifact.Id));}),
        ("reference indexing deduplicates but never edits source metadata",async f=>{var(s,p,file)=await Setup(f);var a=await s.ReferenceFileAsync(file,p.Id);var b=await s.ReferenceFileAsync(file,p.Id);Check(a.Artifact.Id==b.Artifact.Id&&b.AlreadyExists);await Reject(()=>s.UpdateArtifactAsync(a.Artifact.Id,"changed","",p.Id));await Reject(()=>s.RemoveArtifactAsync(a.Artifact.Id));Check((await s.ListAsync()).Count==1);}),
        ("reference rejects outside project and secrets",async f=>{var(s,p,file)=await Setup(f);var outside=f.File("outside.md","no");await Reject(()=>s.ReferenceFileAsync(outside,p.Id));var secret=Path.Combine(p.RootPath!,".env");await File.WriteAllTextAsync(secret,"private");await Reject(()=>s.ReferenceFileAsync(secret,p.Id));}),
        ("reference backup includes metadata without copying source",async f=>{var(s,p,file)=await Setup(f);var r=await s.ReferenceFileAsync(file,p.Id);var zip=Path.Combine(f.Root,"reference-backup.zip");await new PortfolioMaintenance(f.DataRoot).BackupAsync(zip);using var z=System.IO.Compression.ZipFile.OpenRead(zip);Check(!z.Entries.Any(e=>e.FullName.StartsWith("objects/")));Check(await File.ReadAllTextAsync(file)=="needle 原文");}),
        ("reference restore does not open original and resets parsed content",async f=>{var(s,p,file)=await Setup(f);var r=await s.ReferenceFileAsync(file,p.Id);await s.ParseReferenceAsync(r.Artifact.Id);var zip=Path.Combine(f.Root,"reference-restore.zip");var target=Path.Combine(f.Root,"restored");await using(var denied=new FileStream(file,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){await new PortfolioMaintenance(f.DataRoot).BackupAsync(zip);await new PortfolioMaintenance(target).RestoreAsync(zip);}var restored=new PortfolioStore(target);restored.EnableCodexReferenceMode(Path.Combine(f.Root,"codex"));var got=await restored.GetAsync(r.Artifact.Id);Check(got!.IsReference&&got.Preview==""&&got.Hash==""&&got.ExtractionStatus=="未解析");Check(await File.ReadAllTextAsync(file)=="needle 原文"&&(!Directory.Exists(Path.Combine(target,"objects"))||!Directory.EnumerateFiles(Path.Combine(target,"objects")).Any()));})
    ];
    internal static async Task<(PortfolioStore Store,ProjectRecord Project,string File)> Setup(Fixture f)
    {
        var directory=Directory.CreateDirectory(Path.Combine(f.ReferenceRoot,"project")).FullName;var file=Path.Combine(directory,"notes.md");await File.WriteAllTextAsync(file,"needle 原文");var home=Path.Combine(f.Root,"codex");Directory.CreateDirectory(home);
        await File.WriteAllTextAsync(Path.Combine(home,".codex-global-state.json"),JsonSerializer.Serialize(new Dictionary<string,object>{{"local-projects",new Dictionary<string,object>{{"p",new{id="p",name="Test",rootPaths=new[]{Path.GetDirectoryName(file)!}}}}}}));
        var s=new PortfolioStore(f.DataRoot);s.EnableCodexReferenceMode(home);await s.RefreshCodexProjectsAsync();return(s,(await s.ProjectsAsync()).Single(),file);
    }
    private static void Check(bool value){if(!value)throw new Exception("reference invariant failed");}
    private static async Task Reject(Func<Task> action){try{await action();}catch(Exception e)when(e is IOException or UnauthorizedAccessException or NotSupportedException or InvalidOperationException){return;}throw new Exception("expected read-only rejection");}
}
